const CARDS_ETHICS_CONSENT = [
  { q: "What are the <b>4 elements of valid informed consent</b>?", a: "<b>1. Disclosure</b> — adequate information (diagnosis, procedure, risks, benefits, alternatives, including no treatment)<br><b>2. Understanding</b> — patient comprehends the information<br><b>3. Voluntariness</b> — free from coercion or undue influence<br><b>4. Decision-making capacity</b> — patient has capacity to decide<br><i>All 4 must be present for consent to be valid</i>" },
  { q: "What information must be <b>disclosed</b> during informed consent?", a: "<b>Required disclosure:</b><br>• Diagnosis and nature of condition<br>• Proposed procedure/treatment<br>• Material risks (those a reasonable patient would consider significant)<br>• Benefits of proposed treatment<br>• Reasonable alternatives<br>• Consequences of declining treatment<br><i>Standard: 'reasonable patient' standard (majority) OR 'reasonable physician' standard (minority)</i>" },
  { q: "What is <b>decision-making capacity</b> (DMC)?", a: "Patient's ability to make a specific medical decision at a specific time<br><br><b>4 components (MacArthur criteria):</b><br>1. <b>Understand</b> — comprehend information provided<br>2. <b>Appreciate</b> — recognize how it applies to their situation<br>3. <b>Reason</b> — weigh risks/benefits logically<br>4. <b>Communicate</b> — express a consistent choice<br><br><i>Capacity is decision-specific and time-specific</i>" },
  { q: "How does <b>capacity</b> differ from <b>competency</b>?", a: "<b>Capacity:</b> Clinical determination made by physician at the bedside — can patient make this decision NOW?<br><br><b>Competency:</b> Legal determination made by a court judge<br><br><i>Physicians assess capacity; courts determine competency. In practice, a patient with capacity is presumed legally competent. A physician can declare a patient lacks capacity; a judge declares incompetency.</i>" },
  { q: "A patient refuses a blood transfusion. They seem confused. What is the <b>first step</b>?", a: "<b>Assess decision-making capacity</b><br><br>• Capacity is required for refusal to be valid<br>• If patient lacks capacity → surrogate decision-maker<br>• If patient HAS capacity → even life-threatening refusal must be respected (e.g., Jehovah's Witness)<br><br><i>Never assume incapacity due to diagnosis alone (e.g., dementia, psych disorder)</i>" },
  { q: "What is the <b>Mini-Mental State Examination (MMSE)</b> and its role in capacity?", a: "<b>MMSE</b> is a cognitive screening tool (score 0-30)<br><br>• <b>NOT</b> a direct test of decision-making capacity<br>• Low MMSE does not automatically mean incapacity<br>• A patient with low MMSE may still have capacity for simple decisions<br>• A patient with normal MMSE may lack capacity (e.g., delusional disorder)<br><br><i>Capacity requires functional ability to understand, appreciate, reason, and communicate — not just cognitive score</i>" },
  { q: "Which clinician should assess <b>decision-making capacity</b>?", a: "<b>Any licensed physician</b> can assess capacity for routine decisions<br><br>• Attending physician typically assesses<br>• <b>Psychiatry consult</b> recommended for: borderline cases, psychiatric illness, complex decisions, legal implications<br>• Ethics committee consult for value conflicts<br><br><i>No special certification required; however, documentation must reflect all 4 MacArthur criteria</i>" },
  { q: "What happens when a patient <b>lacks decision-making capacity</b>?", a: "<b>Surrogate decision-maker</b> (proxy) is used<br><br><b>Hierarchy (varies by state):</b><br>1. Legal healthcare proxy / healthcare power of attorney<br>2. Spouse or domestic partner<br>3. Adult children (majority)<br>4. Parents<br>5. Adult siblings<br>6. Close friends<br>7. Court-appointed guardian<br><br><i>If no surrogate available and non-emergent: seek court authorization. Emergencies: treat without consent.</i>" },
  { q: "What is a <b>Healthcare Power of Attorney (HCPOA)</b>?", a: "A legal document designating a <b>healthcare proxy/agent</b> to make medical decisions when the patient lacks capacity<br><br>• Also called: Durable Power of Attorney for Healthcare, Healthcare Proxy<br>• Agent uses <b>substituted judgment</b> standard — 'what would the patient want?'<br>• Activated only when patient lacks capacity<br>• Can be revoked by patient at any time while they have capacity<br><br><i>This is the PREFERRED advance directive for decision-making</i>" },
  { q: "What is <b>substituted judgment</b> vs <b>best interest standard</b>?", a: "<b>Substituted judgment:</b> Surrogate decides as the patient would — based on patient's known values, beliefs, prior statements (preferred standard)<br><br><b>Best interest standard:</b> Used when patient's wishes are unknown — surrogate decides based on what a 'reasonable person' would want in that situation<br><br><i>Substituted judgment > best interest. Best interest is a fallback.</i>" },
  { q: "What are <b>advance directives</b>?", a: "Legal documents expressing a patient's wishes about future medical care if they lose decision-making capacity<br><br><b>Types:</b><br>1. <b>Living will</b> — specifies what treatments patient wants/refuses<br>2. <b>Healthcare proxy/HCPOA</b> — designates decision-maker<br>3. <b>Do Not Resuscitate (DNR)/DNAR</b> — physician order<br>4. <b>POLST/MOLST</b> — Physician/Medical Orders for Life-Sustaining Treatment<br><br><i>Advance directives are honored only when patient lacks capacity</i>" },
  { q: "What is a <b>living will</b>?", a: "Written advance directive specifying patient's treatment preferences for specific future scenarios (e.g., terminal illness, persistent vegetative state)<br><br>• May include preferences about: ventilation, CPR, artificial nutrition, dialysis, antibiotics<br>• Activated only when: <b>patient lacks capacity</b> AND <b>scenario described occurs</b><br>• Less flexible than HCPOA<br><br><i>Living will tells WHAT to do; HCPOA names WHO decides</i>" },
  { q: "A competent patient refuses a life-saving amputation. What do you do?", a: "<b>Respect the refusal</b><br><br>• Competent patients have the right to refuse ANY treatment, even life-saving<br>• Document the discussion, ensure understanding of consequences<br>• Ensure the refusal is informed (patient understands risks of refusal)<br>• May offer palliative care<br><br><i>Autonomy: right to refuse treatment is absolute in competent adults. You cannot force treatment over competent refusal.</i>" },
  { q: "What is <b>implied consent</b>?", a: "Consent inferred from patient's behavior or circumstances — without explicit verbal/written agreement<br><br><b>Examples:</b><br>• Patient extends arm for blood draw (emergency/routine)<br>• Patient presents to ER unconscious → consent implied for life-saving treatment<br><br><i>Emergency exception: when patient cannot consent, treatment is implied in emergencies to prevent serious harm/death. Implied consent does not apply to elective procedures.</i>" },
  { q: "What is the <b>emergency exception</b> to informed consent?", a: "In true emergencies, when a patient cannot provide consent and delay would cause serious harm or death:<br>• Treat without consent<br>• Based on <b>implied consent doctrine</b> — reasonable person would want treatment<br><br><b>Conditions:</b><br>1. Immediate threat to life or serious harm<br>2. Patient unable to consent<br>3. No time to obtain surrogate<br>4. No known prior refusal<br><br><i>Exception does NOT apply if patient has a valid advance directive refusing treatment</i>" },
  { q: "Can a <b>minor</b> give informed consent?", a: "<b>Generally NO</b> — parents/guardians provide consent for minors (<18 years)<br><br><b>Exceptions where minors can consent independently:</b><br>• <b>Emancipated minors</b> (married, military, financially independent, court-ordered)<br>• <b>Mature minor doctrine</b> (case-by-case, sufficient maturity/understanding)<br>• <b>Specific services</b> (state-specific): STIs/sexual health, contraception, substance abuse, mental health (most states allow 12-14+)<br><br><i>Assent (minor's agreement) is still sought even when not legally required</i>" },
  { q: "What are the <b>emancipated minor</b> criteria?", a: "A minor who is legally treated as an adult for medical decision-making:<br><br>• Married (even if divorced)<br>• Active military service<br>• Financially self-supporting and living independently<br>• Parent of own child<br>• Court-declared emancipation<br><br><i>Emancipated minors can consent to all medical treatments, not just specific services</i>" },
  { q: "What is the <b>mature minor doctrine</b>?", a: "Allows a minor who demonstrates sufficient maturity and understanding to consent to medical treatment without parental consent<br><br>• Recognition: most US states (varies by state)<br>• Factors: age (typically 14+), ability to understand consequences, prior medical experience<br>• Not applicable in all states<br><br><i>Assent vs Consent: even non-emancipated, non-mature minors should be asked for 'assent' — their agreement, even if not legally binding</i>" },
  { q: "A 15-year-old requests <b>birth control</b> without parental consent. What do you do?", a: "<b>Provide contraception</b> without parental notification in most states<br><br>• Most states allow minors to consent independently to: contraception, STI testing/treatment, pregnancy care<br>• Encourage parental involvement but cannot require it<br>• Maintain confidentiality<br><br><i>Key USMLE point: confidentiality for minors seeking reproductive/STI/substance abuse care is protected in most states</i>" },
  { q: "What is <b>therapeutic privilege</b>?", a: "Withholding information from a patient if disclosure would cause serious psychological harm<br><br>• <b>Rarely justified</b> in modern medical ethics<br>• Paternalistic and controversial<br>• Cannot withhold information just because patient might refuse treatment<br>• Cannot withhold information to avoid distress<br><br><i>Therapeutic privilege is NOT justified simply because the patient might become upset or refuse treatment. It is only valid if disclosure would cause actual harm (e.g., severe psychiatric decompensation)</i>" },
  { q: "What is <b>waiver of informed consent</b>?", a: "A competent patient voluntarily waives the right to receive detailed information before treatment<br><br>• Patient states they trust the physician and don't want details<br>• Still must confirm voluntariness and competency<br>• Document waiver<br><br><i>Waiver is valid — patients can choose NOT to be informed. However, the patient must still be informed of their right to information. Cannot be coerced into waiving.</i>" },
  { q: "What is <b>research consent</b> vs clinical consent?", a: "<b>Research consent</b> has additional requirements (Belmont Report/federal regulations):<br>• Purpose of the research must be explained<br>• That participation is voluntary and can be withdrawn<br>• Expected duration of participation<br>• Foreseeable risks AND discomforts<br>• Anticipated benefits (to subject or others)<br>• Alternative treatments available<br>• Confidentiality protections<br>• Compensation for injury information<br><br><i>IRB (Institutional Review Board) must approve research protocols. Research consent is more stringent than clinical consent.</i>" },
  { q: "What is the role of an <b>Institutional Review Board (IRB)</b>?", a: "Independent committee that reviews, approves, and monitors research involving human subjects<br><br><b>Responsibilities:</b><br>• Ensure research benefits outweigh risks<br>• Verify informed consent process<br>• Protect vulnerable populations (children, prisoners, pregnant women)<br>• Monitor ongoing research<br><br><i>Mandated by the Belmont Report (1979) and federal law (45 CFR 46). Research cannot begin without IRB approval.</i>" },
  { q: "What are the <b>3 Belmont Report principles</b> for research ethics?", a: "<b>1. Respect for Persons</b> — autonomy: informed consent, protect those with diminished autonomy<br><b>2. Beneficence</b> — do good, minimize harm; maximize benefits and minimize risks<br><b>3. Justice</b> — equitable selection of subjects; don't exploit vulnerable groups; distribute benefits and burdens fairly<br><br><i>Published 1979 after Tuskegee syphilis study scandal. Foundation of US human subjects research regulations</i>" },
  { q: "What was the <b>Tuskegee syphilis study</b> and its ethical significance?", a: "<b>1932-1972</b>: US Public Health Service studied untreated syphilis in 399 African American men in Alabama<br><br>• Penicillin became available 1947 — NOT given to subjects<br>• Men not told they had syphilis or that treatment was withheld<br>• Led to <b>National Research Act (1974)</b> and <b>Belmont Report (1979)</b><br><br><b>Legacy:</b> Established need for IRBs, informed consent in research, and protection of vulnerable populations</i>" },
  { q: "What is the <b>Canterbury v. Spence</b> case significance?", a: "Landmark 1972 US federal case establishing the <b>patient-centered (reasonable patient) standard</b> for informed consent disclosure<br><br>• Physician failed to disclose 1% risk of paralysis from laminectomy<br>• Court ruled: disclosure must cover information that a <b>reasonable patient</b> would consider material to their decision<br><br><i>Majority US standard. Contrast with older 'professional standard' — what a reasonable physician would disclose</i>" },
  { q: "What is the <b>professional/physician standard</b> for informed consent?", a: "Disclosure obligation is what a <b>reasonable physician</b> in the same specialty would disclose in similar circumstances<br><br>• Minority standard in US<br>• Criticized as paternalistic — physicians decide what patients need to know<br><br><i>Compare with 'reasonable patient' standard (majority): what a reasonable patient would want to know. USMLE favors the reasonable patient standard.</i>" },
  { q: "When can physicians <b>disclose patient information</b> without consent?", a: "<b>Mandatory reporting exceptions:</b><br>• <b>Communicable diseases</b> (TB, STIs, COVID — state-specific lists)<br>• <b>Child abuse</b> (suspected, mandatory reporter)<br>• <b>Elder abuse</b><br>• <b>Gunshot/stab wounds</b> (most states)<br>• <b>Tarasoff duty to warn</b> (specific, credible threat to identifiable third party)<br>• Court orders / subpoenas<br>• Workers' compensation claims (limited)<br><br><i>Privacy broken for public safety, not convenience</i>" },
  { q: "What is the <b>Tarasoff duty to warn</b>?", a: "<b>Tarasoff v. Regents of UC (1976):</b> Therapist must take reasonable steps to protect an identifiable third party from a patient's serious, credible threat of harm<br><br><b>Duty triggered by:</b><br>• Serious threat (violence/harm)<br>• Identifiable victim<br>• Credible (patient has means/intent)<br><br><b>Actions:</b> Warn the intended victim, notify police, hospitalize patient (involuntary if needed), or some combination<br><br><i>Overrides confidentiality. Not all states have adopted Tarasoff; some have discretionary duty.</i>" },
  { q: "What is <b>HIPAA</b> and what does it protect?", a: "<b>Health Insurance Portability and Accountability Act (1996)</b><br><br>Protects <b>Protected Health Information (PHI)</b>:<br>• Any identifiable health information (name, DOB, SSN, address, diagnosis, etc.)<br><br><b>Permitted disclosures without authorization:</b><br>• Treatment, Payment, Healthcare Operations (TPO)<br>• Public health reporting<br>• Law enforcement (limited)<br>• Emergency situations<br><br><i>Patients have rights to: access records, amend records, receive accounting of disclosures, request restrictions</i>" },
  { q: "Under HIPAA, who can access a patient's medical records?", a: "<b>Access without patient authorization:</b><br>• Treating physicians (treatment)<br>• Insurers (payment)<br>• Quality review/accreditation (operations)<br>• Public health authorities<br><br><b>Requires patient authorization:</b><br>• Employers (except workers' comp)<br>• Life/disability insurers<br>• Family members (unless designated proxy or patient authorizes)<br>• Media<br>• Attorneys (except court order)<br><br><i>Even spouses do NOT have automatic right to PHI without patient authorization</i>" },
  { q: "A patient is brought in unconscious. Family requests information. What do you do?", a: "May share information with family if:<br>• Patient previously authorized disclosure to that family member<br>• Physician determines it is in the patient's best interest<br>• Information shared is limited to what's needed for care coordination<br><br><i>Unconscious patient cannot consent — apply emergency exception and use clinical judgment. Document reasoning. Once patient regains capacity, they resume control of their information.</i>" },
  { q: "What is the <b>right to refuse treatment</b> based on?", a: "Based on <b>autonomy</b> and the constitutional right to liberty (14th Amendment)<br><br>Legal precedents:<br>• <i>Cruzan v. Director, Missouri Dept. of Health (1990)</i> — SCOTUS: competent patients have constitutional right to refuse treatment including withdrawal of life-sustaining treatment<br>• <i>Schloendorff v. Society of NY Hospital (1914)</i> — Cardozo: 'every human being of adult years and sound mind has the right to determine what shall be done with his own body'<br><br><i>Refusal is only valid if patient has decision-making capacity</i>" },
  { q: "What is the legal standard for <b>involuntary psychiatric hospitalization</b>?", a: "Patient must meet criteria for <b>danger to self</b> (suicidal) OR <b>danger to others</b> OR <b>unable to care for self</b> due to mental illness<br><br><b>Process:</b><br>• Emergency holds: physician/police can initiate 72-hour hold (5150 in CA)<br>• Must have formal hearing for longer commitment<br>• Patient retains rights (to attorney, to challenge commitment)<br><br><i>Mental illness alone is NOT sufficient. Must demonstrate imminent danger.</i>" },
  { q: "A psychotic patient refuses antipsychotics. Can you force medication?", a: "<b>Generally NO</b> — even involuntarily hospitalized patients retain right to refuse medication<br><br><b>Exceptions:</b><br>• Imminent danger to self or others (emergency situation)<br>• Court order (after due process hearing)<br><br><i>Involuntary hospitalization ≠ right to force medication. Separate legal proceedings needed for forced medication in non-emergency. Riese hearings (CA) / Rogers hearings (MA) are examples.</i>" },
  { q: "What is <b>informed refusal</b>?", a: "A competent patient's documented decision to decline recommended treatment after being fully informed<br><br>• Physician must document: patient was informed of diagnosis, risks of refusal, alternatives<br>• Patient understands consequences<br>• Decision is voluntary<br>• Patient has decision-making capacity<br><br><i>Informed refusal carries same weight as informed consent. Document thoroughly. Cannot be undone by physician unilaterally.</i>" },
  { q: "A patient with <b>depression</b> refuses chemotherapy. Do they lack capacity?", a: "<b>NOT automatically</b> — psychiatric diagnosis does NOT equal incapacity<br><br>• Must formally assess all 4 components of DMC<br>• Depression may impair appreciation ('I'm not worth saving') → suggests incapacity<br>• If depressed patient understands, appreciates, reasons, and communicates → has capacity<br>• Treat depression and reassess<br><br><i>The decision to refuse (even for poor reasons) does not equal incapacity. Focus on the PROCESS of decision-making, not the outcome.</i>" },
  { q: "What is a <b>DNR/DNAR order</b>?", a: "<b>Do Not Resuscitate / Do Not Attempt Resuscitation</b> — physician order directing that CPR not be performed if patient has cardiopulmonary arrest<br><br>• Requires informed consent from patient (or surrogate if incapacitated)<br>• Does NOT mean 'do not treat' — other treatments continue<br>• Automatically suspended during general anesthesia (unless specifically discussed)<br>• Must be rewritten with each hospital admission<br><br><i>DNR ≠ withdrawal of care. Misunderstanding this is a common error.</i>" },
  { q: "What is <b>POLST</b> and how does it differ from a living will?", a: "<b>POLST (Physician Orders for Life-Sustaining Treatment)</b> — also MOLST, MOST, POST depending on state<br><br>• Medical ORDER (not just a directive) — immediately actionable<br>• Signed by physician AND patient<br>• Travels with patient across care settings<br>• Covers: CPR, hospitalization, artificial nutrition, ventilation<br><br><b>vs Living Will:</b><br>• Living will = patient document; POLST = physician order<br>• POLST is more specific and immediately enforceable<br><br><i>Ideal for seriously ill or frail patients</i>" },
  { q: "Under what circumstances should a physician <b>override a patient's stated wishes</b>?", a: "<b>Almost never</b> for a competent patient. Exceptions:<br>• Patient currently lacks capacity (prior wishes may be overridden by proper surrogate)<br>• Public health emergency (quarantine, mandatory reporting)<br>• Court order<br>• Patient is a minor (parental override in some cases)<br><br><i>Even lifestyle-endangering or medically inadvisable decisions must be respected if made by a competent adult. Physician should express disagreement but comply (or transfer care).</i>" },
  { q: "What is the <b>National Practitioner Data Bank (NPDB)</b>?", a: "Federal database of reports on physicians and other healthcare practitioners<br><br><b>Reports required for:</b><br>• Medical malpractice payments<br>• Adverse licensure actions<br>• Adverse clinical privilege actions<br>• Exclusions from Medicare/Medicaid<br>• Criminal convictions related to healthcare<br><br><i>Hospitals must query NPDB when credentialing physicians. NPDB protects confidentiality — not available to public</i>" },
  { q: "What are <b>conditions for valid consent in research</b> (beyond clinical care)?", a: "<b>Federal regulations (45 CFR 46) require:</b><br>1. Voluntary participation (right to withdraw without penalty)<br>2. Purpose and duration of research explained<br>3. Foreseeable risks and discomforts disclosed<br>4. Expected benefits explained<br>5. Alternatives described<br>6. Confidentiality protections<br>7. Compensation for injury policy<br>8. Contact information (questions/injury)<br>9. Statement that participation is voluntary<br><br><i>Additional protections for vulnerable populations: children, prisoners, pregnant women</i>" },
  { q: "When can informed consent be <b>waived in research</b>?", a: "IRB may waive consent if ALL of:<br>1. Research involves minimal risk<br>2. Waiver won't adversely affect subjects' rights<br>3. Research could not practicably be done without waiver<br>4. Subjects will be debriefed when appropriate<br><br><b>Examples:</b><br>• Chart reviews (retrospective, de-identified)<br>• Some observational studies<br>• Emergency research (separate regulations)<br><br><i>NOT waived simply for convenience or to increase enrollment</i>" },
  { q: "What is <b>assent</b> in pediatric medicine?", a: "A child's affirmative agreement to participate in research or medical treatment — distinct from legal consent (given by parent/guardian)<br><br>• Sought from children age <b>7-14+</b> (varies by institution)<br>• <b>Not legally required</b> but ethically important<br>• Child's dissent should be respected unless treatment is essential<br>• Documents respect for developing autonomy<br><br><i>Assent ≠ consent. Parent gives consent; child gives assent. If child dissents, carefully consider whether to proceed.</i>" },
  { q: "What is the <b>surrogate decision-making hierarchy</b> in most US states?", a: "<b>Priority order (varies by state):</b><br>1. Healthcare proxy/agent (HCPOA) — if designated<br>2. Court-appointed guardian<br>3. Spouse/domestic partner<br>4. Adult child (or majority of adult children)<br>5. Parent<br>6. Adult sibling<br>7. Close friend<br><br><i>Always check state law. If designated HCPOA exists, they supersede family hierarchy. If no surrogate exists → ethics committee or court</i>" },
  { q: "A patient designates their <b>adult daughter</b> as HCPOA. The spouse disagrees. Who decides?", a: "<b>The HCPOA (adult daughter)</b> — designated healthcare proxy supersedes default surrogate hierarchy<br><br>• HCPOA was legally designated by patient when they had capacity<br>• Patient's autonomous choice of agent must be honored<br>• Spouse has no authority to override the designated agent<br><br><i>Key principle: the designated HCPOA takes precedence over next-of-kin hierarchy</i>" },
  { q: "What is <b>surrogate decision-making conflict</b> and how is it resolved?", a: "When surrogates disagree (e.g., adult children can't agree) or surrogate decisions seem inconsistent with patient's known wishes<br><br><b>Steps:</b><br>1. Family meeting — facilitate discussion<br>2. Social work involvement<br>3. Palliative care consultation<br>4. Ethics committee consultation<br>5. Court involvement (last resort)<br><br><i>Goal: determine patient's authentic wishes using substituted judgment, not what family wants</i>" },
  { q: "What is the role of the <b>hospital ethics committee</b>?", a: "<b>Ethics committees</b> provide:<br>• Consultation on difficult ethical cases<br>• Policy development (DNR, consent, end-of-life)<br>• Education for staff<br>• Review of ethics violations<br><br>Consultations requested when:<br>• Disagreement about care plan<br>• Unclear advance directives<br>• Surrogate conflict<br>• Withholding/withdrawing treatment disputes<br><br><i>Advisory — not binding. Final decisions rest with patient, surrogate, or court</i>" },
  { q: "A Jehovah's Witness adult refuses a blood transfusion needed for survival. What do you do?", a: "<b>Respect the refusal</b> if patient has decision-making capacity<br><br>• Confirm capacity is intact<br>• Ensure decision is informed (knows the risk of death)<br>• Ensure decision is voluntary (not coerced by family/church)<br>• Document thoroughly<br>• Offer bloodless surgery alternatives if possible<br>• Do NOT transfuse over patient's objection<br><br><i>If patient loses capacity: follow advance directive or surrogate. If minor Jehovah's Witness: court order can be sought to transfuse to save life.</i>" },
  { q: "A Jehovah's Witness <b>minor</b> (parents refuse) needs blood transfusion. What do you do?", a: "<b>Seek emergency court order</b> to transfuse<br><br>• Minors cannot legally refuse life-saving treatment on religious grounds<br>• Parents' religious rights do not extend to denying life-saving treatment to minors<br>• In true emergency (no time for court) → treat to save life<br><br><i>Legal precedent: Parens patriae doctrine — state can override parental decisions when child's life is at risk. Adults can choose death; children cannot.</i>" },
  { q: "What is <b>informed consent for surgery</b> — who obtains it?", a: "<b>The performing surgeon</b> is responsible for obtaining informed consent<br><br>• Can delegate to physician assistant/resident who is familiar with the procedure<br>• Must ensure patient received adequate information<br>• Anesthesiologist obtains separate consent for anesthesia<br><br><i>Nursing staff do NOT obtain surgical consent (they may witness signature). The proceduralist bears responsibility.</i>" },
  { q: "What happens if a patient signs a consent form but doesn't understand what they signed?", a: "The consent is <b>NOT valid</b><br><br>• Signature alone does not constitute informed consent<br>• Patient must demonstrate understanding (not just sign)<br>• If patient cannot understand in English: use a qualified medical interpreter (not family member)<br>• If patient cannot read: explain verbally, confirm comprehension<br><br><i>Informed consent is a process (discussion), not just a signature on a form</i>" },
  { q: "When must a <b>medical interpreter</b> be used (vs family member)?", a: "<b>Professional/qualified medical interpreter preferred</b> for all clinical interactions with LEP (limited English proficiency) patients<br><br>• Federal law (Title VI Civil Rights Act): hospitals receiving federal funding must provide free language services<br>• Family interpreters: generally discouraged (conflict of interest, privacy, accuracy)<br>• <b>Absolutely avoid</b> using minor children as interpreters<br><br><i>For informed consent: using family interpreter risks invalid consent due to filtering/bias. Use telephonic interpreter if trained interpreter unavailable.</i>" },
  { q: "What is <b>capacity assessment in dementia</b>?", a: "Dementia ≠ automatic incapacity<br><br>• Mild dementia: often retain capacity for simple decisions<br>• Moderate/severe dementia: likely lack capacity for complex decisions<br>• Capacity is decision-specific: may have capacity for some decisions but not others<br>• Assess in 'best window' (morning, after rest, without sedating medications)<br><br><i>Even patients with dementia should be involved in care decisions to the extent possible. 'Assent' is sought even without full capacity.</i>" },
  { q: "What is capacity for a patient with <b>intellectual disability</b>?", a: "Intellectual disability (ID) does not automatically negate capacity<br><br>• Mild ID: often retain decision-making capacity<br>• Moderate/severe ID: frequently lack full capacity<br>• Must formally assess all 4 MacArthur criteria<br>• If lacks capacity: legal guardian provides consent<br>• If guardian not established: may need court appointment<br><br><i>Patients with ID should participate in decision-making to their fullest ability. Person-centered approach.</i>" },
  { q: "What is the <b>fluctuating capacity</b> situation (e.g., ICU delirium)?", a: "Patient's capacity may vary over time<br><br>• Reassess frequently in delirious/encephalopathic patients<br>• Make major decisions when patient is most lucid<br>• For non-emergent decisions: wait for capacity to return<br>• Document each capacity assessment with time and date<br><br><i>A patient who lacked capacity yesterday may have capacity today. Prior incapacity does not permanently invalidate future decision-making.</i>" },
  { q: "What is the '<b>sliding scale</b>' of capacity?", a: "The threshold for demonstrating decision-making capacity scales with the <b>risk of the decision</b>:<br><br>• <b>Low-risk decision</b> (e.g., taking aspirin): low threshold — basic understanding sufficient<br>• <b>High-risk decision</b> (e.g., refusing surgery needed to survive): higher threshold — must clearly demonstrate all 4 components<br><br><i>Proposed by Appelbaum & Grisso. Not universally adopted as formal standard but reflects clinical practice</i>" },
  { q: "A patient says 'I'll sign whatever, just do whatever you think is best.' Is this valid consent?", a: "<b>Not automatically</b> — this is a potential waiver of informed consent<br><br>• Confirm patient has capacity<br>• Confirm the waiver is voluntary (not coercion)<br>• Document that patient was offered information and chose to waive<br>• Note that waiver can be revoked at any time<br>• Still cannot proceed if patient previously expressed specific refusals<br><br><i>A voluntary waiver of information is valid. A coerced waiver is not.</i>" },
  { q: "What is <b>coercion</b> in the context of informed consent?", a: "Undue pressure that undermines voluntariness of consent<br><br><b>Forms of coercion:</b><br>• Explicit threats (e.g., 'if you don't consent, we won't treat you')<br>• Undue inducements (excessive payment for research participation)<br>• Pressure from family members<br>• Physician's own bias presented as fact<br><br><i>Consent obtained under coercion is invalid. Voluntariness is one of the 4 core elements of informed consent.</i>" },
  { q: "What does 'material risk' mean in informed consent?", a: "A risk is 'material' if it would be significant to a <b>reasonable patient</b> in deciding whether to undergo the procedure<br><br>• Material risks MUST be disclosed<br>• Low-probability but high-severity risks are material (e.g., death, paralysis, loss of organ)<br>• High-probability but minor risks are material (e.g., post-op pain, bruising)<br>• Does not require disclosing every theoretical risk<br><br><i>Test: would a reasonable patient want to know? If yes → disclose</i>" },
  { q: "What is the <b>doctrine of informed consent</b> and its legal basis?", a: "Legal/ethical doctrine requiring physicians to disclose material information to patients before obtaining consent for treatment<br><br><b>Legal foundations:</b><br>• Common law (battery — touching without consent)<br>• Negligence (failing to disclose material information = malpractice)<br>• Constitutional privacy rights<br><br><i>Failure to obtain valid informed consent = battery (unauthorized touching) OR negligence (if proper disclosure would have changed patient's decision)</i>" },
  { q: "What is the difference between <b>battery</b> and <b>negligence</b> in informed consent?", a: "<b>Battery:</b> Unauthorized touching — performing a procedure the patient did NOT consent to at all (e.g., operating on wrong site, performing additional procedure without prior consent)<br><br><b>Negligence:</b> Consent given but disclosure was inadequate — patient consented but wasn't told of a material risk that would have changed their decision<br><br><i>Most modern informed consent lawsuits are brought as negligence, not battery</i>" },
  { q: "A patient consented to appendectomy. During surgery, surgeon discovers colon cancer and removes it. Battery?", a: "<b>Yes — potentially battery</b> (unauthorized procedure)<br><br>• Consent was for appendectomy only<br>• Extending to additional procedure (colectomy) without prior consent = battery<br>• Exception: patient is under anesthesia and delay would cause serious harm (e.g., actively bleeding tumor) → <i>implied emergency consent</i><br><br><i>Best practice: discuss with patient in advance what to do if additional pathology is found. If non-urgent → wake patient up and discuss</i>" },
  { q: "What is <b>therapeutic misconception</b> in research?", a: "Research participants believe the primary purpose of the study is to benefit them personally, when research's primary goal is to generate generalizable knowledge<br><br>• Common in clinical trials<br>• Undermines voluntary informed consent<br>• Investigators must clearly distinguish research from treatment<br><br><i>Participants may confuse 'experimental treatment' with 'best treatment'. Investigators must clarify the experimental nature and that assignment (randomization) is not tailored to individual benefit</i>" },
  { q: "What are <b>vulnerable populations</b> in research and what protections apply?", a: "<b>Vulnerable populations</b> receive additional protections:<br>• <b>Children</b> — parental permission + child assent; most research requires parental consent<br>• <b>Prisoners</b> — limited to research directly benefiting prisoners or the class; must not offer undue inducement<br>• <b>Pregnant women</b> — research must offer benefit to woman/fetus or minimal risk<br>• <b>Cognitively impaired</b> — LAR (Legally Authorized Representative) gives permission<br><br><i>Additional Subpart protections in 45 CFR 46 (Subparts B, C, D)</i>" },
  { q: "What is a <b>certificate of confidentiality</b> in research?", a: "Issued by NIH — protects researchers from compelled legal disclosure of identifiable research data<br><br>• Protects even from court subpoenas<br>• Allows participants to refuse disclosure to law enforcement<br>• Encourages enrollment in sensitive research (substance abuse, mental health, genetics)<br><br><i>Mandatory for NIH-funded research involving sensitive data since 2017</i>" },
  { q: "What is the <b>Nuremberg Code</b>?", a: "First international code of research ethics — established after Nuremberg trials (1947) regarding Nazi human experimentation<br><br><b>Key principles:</b><br>1. Voluntary consent is absolutely essential<br>2. Experiment must be necessary and fruitful<br>3. Based on animal experiments first<br>4. Avoid unnecessary physical/mental harm<br>5. No experiment if death/disabling injury expected<br>6. Risk must be proportional to humanitarian importance<br>7. Subjects must be protected<br>8. Only conducted by scientifically qualified persons<br>9. Subject can withdraw at any time<br>10. Investigator must stop if injury becomes likely" },
  { q: "What is the <b>Declaration of Helsinki</b>?", a: "World Medical Association (WMA) 1964 document (revised multiple times) — ethical principles for medical research involving human subjects<br><br><b>Key points:</b><br>• Physician-researcher has primary duty to patient welfare<br>• Independent ethics committee review required<br>• Vulnerable subjects need extra protection<br>• Research must be based on adequate laboratory/animal work<br>• Control groups: best proven standard (not placebo if proven treatment exists)<br>• Post-trial access to beneficial treatments<br><br><i>International standard, updated most recently 2013</i>" },
  { q: "What is a <b>randomized controlled trial (RCT)</b> and its ethical requirements?", a: "Gold standard experimental design: participants randomly assigned to intervention vs control<br><br><b>Ethical requirements:</b><br>• <b>Equipoise</b> — genuine uncertainty which treatment is better<br>• Informed consent including disclosure of randomization<br>• IRB approval<br>• Data Safety Monitoring Board (DSMB) for ongoing safety<br>• Stopping rules defined in advance<br><br><i>Clinical equipoise justifies randomization. If one arm proves superior during trial → study should be stopped (DSMB responsibility)</i>" },
  { q: "What is <b>clinical equipoise</b>?", a: "Genuine uncertainty in the medical community about which of the trial treatments is superior<br><br>• Justifies randomization in an RCT<br>• Without equipoise → unethical to randomize patients to potentially inferior treatment<br>• If equipoise is broken (clear evidence of superiority) → trial should stop<br><br><i>Concept introduced by Benjamin Freedman (1987). Distinct from individual uncertainty — requires collective medical community uncertainty</i>" },
  { q: "What is a <b>Data Safety Monitoring Board (DSMB)</b>?", a: "Independent committee that monitors ongoing clinical trials for safety and efficacy<br><br><b>Responsibilities:</b><br>• Review interim data (investigators remain blinded)<br>• Assess adverse events<br>• Recommend stopping the trial if: clear superiority of one arm, unacceptable harm, or futility<br><br><i>DSMB exists to protect trial participants and maintain scientific integrity. Sponsors and investigators should not have access to unblinded interim data.</i>" },
  { q: "What is the difference between <b>Phase I, II, III, IV clinical trials</b>?", a: "<b>Phase I</b>: Safety/toxicity — small group, healthy volunteers (or patients), dose-finding<br><b>Phase II</b>: Efficacy + safety — larger group of patients, preliminary effectiveness<br><b>Phase III</b>: Efficacy vs standard treatment — large RCT, regulatory approval purpose<br><b>Phase IV</b>: Post-marketing surveillance — large population, long-term safety<br><br><i>Phases I-III required for FDA approval. Phase IV occurs after market release.</i>" },
  { q: "What is a <b>placebo</b> and when is its use ethical?", a: "An inert substance given to the control group in a trial<br><br><b>Ethical use of placebo:</b><br>• Acceptable when NO proven effective treatment exists<br>• Acceptable when placebo adds only minimal risk/discomfort<br><br><b>Unethical use:</b><br>• When a proven effective treatment exists — control group should receive best proven treatment (Declaration of Helsinki)<br><br><i>Exception: placebo add-on design (placebo + standard care vs active + standard care) may be ethical even when treatment exists</i>" },
  { q: "What is <b>double-blinding</b> in clinical trials and why is it important?", a: "Neither participants NOR investigators know who received treatment vs placebo/control<br><br><b>Importance:</b><br>• Prevents performance bias (investigators treating groups differently)<br>• Prevents ascertainment/detection bias<br>• Prevents placebo effect differences between groups<br>• Strengthens internal validity<br><br><i>Single-blind: only participant blinded. Double-blind: both blinded. Triple-blind: also blinded outcome assessors.</i>" },
  { q: "What is <b>community consent / waiver of individual consent</b> in research?", a: "In some research (especially in emergency or community settings), individual consent is waived and the community is consulted instead<br><br><b>Examples:</b><br>• Cluster randomized trials (randomization at community level)<br>• Emergency research (patients cannot consent, no time)<br>• Public health interventions<br><br><i>FDA 21 CFR 50.24: Exception from Informed Consent (EFIC) for emergency research — requires community consultation, public disclosure, IRB oversight</i>" },
  { q: "What is <b>deception</b> in research and when is it permitted?", a: "Withholding information or providing false information to participants about the research<br><br><b>When permitted (IRB may approve):</b><br>• Study could not be done otherwise<br>• No greater than minimal risk<br>• Participants are debriefed as soon as possible after participation<br><br><b>Examples:</b><br>• Obedience studies (Milgram), conformity studies<br>• Concealed observation studies<br><br><i>Cannot use deception if it would cause participants to refuse if they knew the true nature</i>" },
  { q: "What is the principle of <b>non-malfeasance</b> in the context of consent?", a: "Obligation to 'first, do no harm' (primum non nocere)<br><br>In consent context:<br>• Physician should not perform procedures without valid consent (harm from battery)<br>• Must disclose risks so patient can avoid harm from uninformed decisions<br>• Must NOT coerce patients (psychological harm)<br><br><i>Non-malfeasance sometimes conflicts with autonomy — if patient refuses beneficial treatment, physician's duty to avoid harm conflicts with respecting refusal. Autonomy usually wins in competent adults.</i>" },
  { q: "What is <b>disclosure of medical errors</b> (truth-telling)?", a: "Ethical and legal obligation to inform patients of significant errors in their care<br><br>• <b>Ethical basis</b>: respect for autonomy, honesty, non-deception<br>• <b>Legal basis</b>: most states require disclosure of unanticipated outcomes<br>• Should include: what happened, why, what will be done to address it<br>• Apology laws: in many states, apologies are not admissible as evidence of liability<br><br><i>Disclosure does NOT require admission of fault/negligence. Document the conversation.</i>" },
  { q: "What is a <b>mature minor</b> versus an <b>emancipated minor</b>?", a: "<b>Emancipated minor</b>: Legal status — can consent to ALL medical care (criteria: married, military, self-supporting, parent, court order)<br><br><b>Mature minor</b>: Clinical/case-by-case determination — minor demonstrates sufficient maturity and intelligence to understand consequences; can consent to specific treatments<br><br><i>Emancipated = status-based, automatic. Mature minor = capacity-based, assessed for each decision</i>" },
  { q: "A 16-year-old wants to <b>donate a kidney</b> to a sibling. Can they?", a: "<b>Generally NO</b> — minors cannot consent to non-therapeutic research or non-therapeutic organ donation<br><br>• Organ donation is not for the minor's medical benefit<br>• Even with parental consent, most institutions decline<br>• Requires court involvement and ethics committee review<br>• Most courts do NOT authorize living organ donation from minors<br><br><i>Autonomy of minors is restricted when there is no direct medical benefit and significant risk exists</i>" },
  { q: "What is the difference between <b>consent</b> and <b>assent</b> in pediatric clinical care?", a: "<b>Consent</b>: Legal authorization from parent/guardian (required for treatment)<br><br><b>Assent</b>: Child's active agreement — sought from children typically ages 7-14+<br><br>• Assent is ethically important even though not legally binding<br>• Child's dissent should prompt reconsideration unless treatment is essential<br>• Promotes trust and respects developing autonomy<br><br><i>Both are expected in pediatric care. Assent without parental consent is insufficient for treatment; parental consent without child's assent may be ethically problematic for elective procedures.</i>" },
  { q: "What are <b>advance directives for mental health</b> (psychiatric advance directives)?", a: "Documents specifying a patient's preferences for mental health treatment during future psychiatric crises when they may lack capacity<br><br>• May name a mental health proxy<br>• May specify preferred/refused medications, hospitalization preferences<br>• Recognized in most US states<br>• Can be overridden in emergencies involving imminent danger<br><br><i>Promotes autonomy for patients with serious mental illness who have capacity between episodes</i>" },
  { q: "What is the '<b>ulysses contract</b>'?", a: "An advance directive in which a patient with capacity instructs future providers to override their future refusal of treatment during a psychiatric episode<br><br>• Patient binds their future self to treatment (like Ulysses binding himself to the mast)<br>• Legal status varies by jurisdiction<br>• Ethically controversial — tension between respecting past autonomous wishes vs current stated wishes<br><br><i>Example: bipolar patient in remission instructs that future manic refusal of lithium should be overridden</i>" },
  { q: "What is the role of <b>patient advocates / patient representatives</b> in consent?", a: "Patient advocates assist patients in understanding their rights and navigating the healthcare system<br><br>• Not the same as a surrogate/proxy<br>• Do not make decisions for patients<br>• Help ensure patient's voice is heard<br>• May assist with advance directive completion<br>• Hospital patient representatives handle grievances<br><br><i>Particularly important for vulnerable patients (elderly, LEP, cognitively impaired, institutionalized)</i>" },
  { q: "What constitutes <b>informed consent for HIV testing</b>?", a: "<b>Previously required specific written consent</b> in most states; now most states allow HIV testing with general consent for medical care ('opt-out' approach)<br><br>• CDC recommends routine HIV testing (opt-out) for all 13-64 year olds<br>• Patient must still be informed testing will occur and have right to decline<br>• Positive results: counseling required before disclosure<br>• Confidentiality protected; specific HIPAA provisions apply<br><br><i>Opt-out approach has increased testing rates significantly</i>" },
  { q: "What is <b>genetic testing consent</b> — special considerations?", a: "Genetic testing carries unique informed consent requirements:<br><br>• Implications for biological relatives (not just the patient)<br>• Risk of genetic discrimination (employment, insurance) — GINA Act protects in some contexts<br>• Psychological impact of results<br>• Variants of unknown significance (VUS) — uncertain results<br>• Pre-test counseling (genetic counselor) strongly recommended<br><br><i>Genetic counseling integrates informed consent with psychological support and risk communication</i>" },
  { q: "What is the <b>Genetic Information Nondiscrimination Act (GINA)</b>?", a: "Federal law (2008) prohibiting discrimination based on genetic information:<br><br>• <b>Health insurers</b> cannot deny coverage or charge higher premiums based on genetic information<br>• <b>Employers</b> (>15 employees) cannot use genetic information in hiring, firing, or other employment decisions<br><br><b>Does NOT cover:</b><br>• Life insurance<br>• Disability insurance<br>• Long-term care insurance<br><br><i>Important context for genetic testing consent: GINA protections are limited</i>" },
  { q: "What are the <b>4 ethical principles of biomedical ethics</b> (Beauchamp & Childress)?", a: "<b>Principlism (Georgetown mantra):</b><br>1. <b>Autonomy</b> — respect patient self-determination<br>2. <b>Beneficence</b> — act in patient's best interest<br>3. <b>Non-maleficence</b> — do no harm<br>4. <b>Justice</b> — fair distribution of benefits and burdens<br><br><i>All 4 can conflict — the challenge of medical ethics is balancing them. Autonomy generally prevails in Western medicine for competent adults.</i>" },
  { q: "What is <b>beneficence</b> in the context of informed consent?", a: "Duty to act in the patient's best interest<br><br>In consent context:<br>• Disclosure serves beneficence — patient can make the best decision for themselves<br>• But paternalism (overriding patient wishes 'for their own good') violates autonomy<br>• Beneficence is NOT justification for withholding information or ignoring refusals<br><br><i>Tension: patient's autonomous decision may not align with physician's view of 'best interest'. Autonomy of competent adults generally prevails.</i>" },
  { q: "What is <b>paternalism</b> in medical ethics?", a: "Overriding a patient's autonomous choice to act in what the physician believes is the patient's best interest<br><br><b>Soft paternalism:</b> Intervening when autonomy is compromised (incapacity, coercion) — generally acceptable<br><b>Hard paternalism:</b> Overriding a competent patient's informed decision — generally NOT acceptable in modern bioethics<br><br><i>Example of hard paternalism: refusing to tell patient diagnosis 'to protect them', or forcing treatment on competent patient. Violates autonomy.</i>" },
  { q: "What is <b>capacity assessment tool — MacCAT-T</b>?", a: "<b>MacArthur Competence Assessment Tool for Treatment (MacCAT-T)</b>:<br>Structured interview assessing all 4 components of decision-making capacity:<br><br>1. Understanding<br>2. Appreciation<br>3. Reasoning<br>4. Expressing a choice<br><br>• Semi-structured interview format<br>• Most widely validated capacity assessment tool<br>• Takes ~20 minutes<br>• Used for research and complex clinical cases<br><br><i>Gold standard research tool; clinical capacity assessments often use less formal structured interview</i>" },
  { q: "What is the capacity assessment question for <b>Appreciation</b>?", a: "Testing <b>Appreciation</b>: Does the patient recognize that the information applies to their own situation?<br><br>Example questions:<br>• 'What do you think will happen if you refuse this surgery?'<br>• 'Why do you think the doctors are recommending this treatment?'<br>• 'Do you believe you have [condition]?'<br><br><i>Impaired appreciation: patient says 'I don't have cancer, the doctors are lying' despite evidence. Common in psychosis, severe depression ('I'm not worth saving').</i>" },
  { q: "What is the capacity assessment question for <b>Reasoning</b>?", a: "Testing <b>Reasoning</b>: Can the patient engage in logical reasoning process to weigh options?<br><br>Example questions:<br>• 'What factors led you to that decision?'<br>• 'Can you walk me through how you decided?'<br>• 'What would change your mind?'<br><br><i>Poor reasoning: patient makes decision based on completely irrelevant factors. Good reasoning: patient weighs risks/benefits, even if decision seems unwise to physician. Note: unwise decision ≠ impaired reasoning.</i>" },
  { q: "What is 'understanding' in decision-making capacity assessment?", a: "<b>Understanding</b>: Can the patient comprehend and recall the information disclosed?<br><br>Assessed by: 'Please tell me in your own words what I just explained about your condition and the proposed treatment.'<br><br>• Patient should be able to paraphrase diagnosis, proposed treatment, key risks and benefits, alternatives<br>• Not required to recall everything verbatim<br>• If fails: re-educate in simpler terms; reassess<br><br><i>First component tested. Foundation for all other components.</i>" },
  { q: "What is 'Expressing a choice' in capacity assessment?", a: "<b>Expressing a choice</b>: Can the patient communicate a consistent, stable decision?<br><br>• Lowest threshold component<br>• Patient must be able to state yes or no AND maintain that choice consistently<br>• Inconsistency may indicate delirium, ambivalence, or severe cognitive impairment<br><br><i>Note: the choice must be consistent — not necessarily the same on multiple assessments (patient can change their mind), but stable within a reasonable timeframe</i>" },
  { q: "What is the legal standard for <b>competency to stand trial</b> vs medical decision-making capacity?", a: "<b>Competency to stand trial (Dusky standard):</b><br>• Ability to understand the proceedings and assist in own defense<br>• Criminal law context<br><br><b>Medical decision-making capacity:</b><br>• Ability to understand, appreciate, reason about, and communicate medical decisions<br>• Clinical medicine context<br><br><i>Different standards for different contexts. A patient may lack medical DMC but be competent to stand trial (and vice versa). Both are functional, context-specific assessments.</i>" },
  { q: "What is <b>informed consent in telemedicine</b>?", a: "Telemedicine requires same informed consent elements as in-person care, plus:<br><br>• Disclosure that encounter is conducted via telemedicine<br>• Potential limitations (technology failure, inability to perform physical exam)<br>• Privacy and security protections<br>• Alternative options if patient is uncomfortable with telemedicine<br>• Licensure/jurisdiction disclosure<br><br><i>Many states have specific telemedicine consent statutes. Documenting consent to telemedicine is increasingly standard practice.</i>" },
  { q: "What is <b>organ donation consent</b>?", a: "<b>First-person consent (donor registry):</b> Individual registers as donor while alive — this is legally binding in most states<br><br><b>Family authorization:</b> Next-of-kin can authorize donation if no registry status; cannot override registered donor status<br><br><b>Presumed consent:</b> Some countries (Spain, Austria) — default is donor; opt-out required<br><br><i>US: opt-in system. Hospital staff (organ procurement organization — OPO) approach families. Donor registration status should be checked before family discussion.</i>" },
  { q: "What is the <b>Uniform Anatomical Gift Act (UAGA)</b>?", a: "Model state law governing organ and tissue donation in the US<br><br><b>Key provisions:</b><br>• First-person authorization is legally binding<br>• Family cannot override legally documented donor decision<br>• Allows donation for transplantation, research, education, or therapy<br>• Procurement organizations (OPOs) coordinate donation<br><br><i>All 50 states have adopted UAGA (2006 revision) with minor variations</i>" },
  { q: "What is <b>brain death</b> and its relation to organ donation consent?", a: "<b>Brain death:</b> Complete and irreversible cessation of all brain functions including brainstem<br><br>• Legally dead in all US states<br>• Two physicians (one a neurologist/neurosurgeon) must declare brain death<br>• Family must be informed of death before organ donation discussion<br>• Donation after cardiac death (DCD): separate protocol when brain death criteria not met but life support withdrawal planned<br><br><i>Consent for organ donation is separate from consent for withdrawal of life support. Both require family counseling.</i>" },
  { q: "What is <b>assent in pediatric research</b>?", a: "Positive agreement from child to participate in research<br><br>• Required in addition to parental permission for federally funded research<br>• Age threshold: typically 7 years old (some institutions 6 or 8)<br>• Age-appropriate explanation of research must be provided<br>• Child's dissent generally sufficient to exclude from research (unless no other access to therapy)<br><br><i>Unlike clinical care, research requires additional protections. Child's assent is more weighted in research than in clinical treatment decisions.</i>" },
  { q: "What is the ethical framework for <b>disclosing incidental findings</b> in genetic research?", a: "When research identifies an incidental finding (e.g., genetic variant for disease not being studied):<br><br><b>Duty to return:</b><br>• <i>Actionable</i> findings: generally should be returned (e.g., BRCA mutation, Lynch syndrome)<br>• <i>Non-actionable</i> findings: controversial — some argue no duty to return<br>• Must be addressed in advance in consent form<br><br><i>ACMG (American College of Medical Genetics) recommends returning pathogenic variants in 73 specified genes regardless of study indication</i>" },
  { q: "What is the '<b>right not to know</b>' in genetics?", a: "Patients have the right to decline information about their genetic predispositions<br><br>• Respects autonomy in the opposite direction — right not to be informed<br>• Example: patient doesn't want to know if they carry BRCA mutation<br>• Must be respected — cannot force information on a patient<br><br><i>Tension: if patient's genetic status affects relatives, do relatives have right to information? Physician's duty is primarily to the patient, not relatives — but ethical guidance varies</i>" },
  { q: "What is <b>decisional conflict</b> and how is it managed?", a: "Patient's uncertainty about which healthcare option to choose when faced with a consequential decision<br><br>• Normal part of decision-making; not the same as incapacity<br>• <b>Decision aids</b>: evidence-based tools (videos, written materials) that help patients make informed, values-consistent choices<br>• Shared decision-making (SDM): collaborative process where physician and patient make decisions together<br><br><i>Ottawa Decisional Conflict Scale assesses decisional conflict. Decision aids reduce conflict and improve adherence.</i>" },
  { q: "What is <b>shared decision-making (SDM)</b>?", a: "Collaborative process where physician and patient work together to make healthcare decisions consistent with patient's values and preferences<br><br><b>Components:</b><br>1. Physician presents evidence-based options<br>2. Patient shares values and preferences<br>3. Decision made together<br><br><b>When most appropriate:</b><br>• 'Preference-sensitive' decisions — where options have different tradeoffs<br>• PSA screening, elective surgeries, chronic disease management<br><br><i>SDM is NOT appropriate for emergencies or when one option is clearly superior</i>" },
  { q: "What is the '<b>reasonable patient</b>' vs '<b>reasonable physician</b>' standard for informed consent?", a: "<b>Reasonable patient standard (patient-centered, majority):</b> Disclose what a reasonable patient would want to know<br><br><b>Reasonable physician standard (professional, minority):</b> Disclose what a reasonable physician would disclose<br><br><i>Most US jurisdictions use the reasonable patient standard. USMLE and Step 2 favor this standard. Example: Canterbury v. Spence (1972) established reasonable patient standard in US federal courts.</i>" },
  { q: "What documentation is required after obtaining informed consent?", a: "<b>Documentation should include:</b><br>• Date and time of discussion<br>• Persons present (patient, family if applicable, witnesses)<br>• What was discussed (diagnosis, procedure, risks, benefits, alternatives)<br>• Patient's questions and responses<br>• Patient's decision<br>• Patient's capacity at time of discussion<br>• Signed consent form (for procedures)<br><br><i>The signed form documents the process but the note in the chart is equally important for demonstrating adequate disclosure</i>" },
  { q: "When can a physician <b>refuse to perform</b> a legally permitted procedure due to moral objection (conscientious objection)?", a: "Physician may decline if:<br>• Procedure violates physician's moral or religious beliefs<br>• Physician does NOT withhold this from patient in an emergency<br>• Physician provides adequate referral to a willing provider<br>• Patient care is not abandoned<br><br><b>Examples:</b> Abortion, assisted dying, sterilization<br><br><i>Limits: Cannot refuse care in emergencies. Must ensure patient can access care. Cannot abandon existing patients without proper transfer.</i>" },
  { q: "What is <b>patient abandonment</b>?", a: "Unilateral termination of physician-patient relationship without adequate notice or provision for alternative care<br><br>• Illegal and unethical<br>• Physician can end relationship but must: give adequate notice (typically 30 days), provide emergency care during transition, assist in finding new provider, transfer records<br><br><i>Conscientious objection does NOT give physician the right to abandon patients. Even if refusing a specific procedure, must continue other care or ensure safe transfer.</i>" },
  { q: "What is the difference between <b>confidentiality</b> and <b>privacy</b> in medicine?", a: "<b>Privacy</b>: Patient's right to control access to their personal information and body<br><br><b>Confidentiality</b>: Physician's duty to protect information shared within the therapeutic relationship<br><br>• Privacy is a right (broader concept)<br>• Confidentiality is a professional obligation (narrower, applies to clinical disclosures)<br>• Both are protected by HIPAA, common law, and professional ethics codes<br><br><i>Confidentiality is derived from respect for privacy. Breaching confidentiality violates patient privacy.</i>" },
  { q: "What is the <b>Cruzan v. Director</b> case significance?", a: "<b>Cruzan v. Director, Missouri Dept. of Health (1990)</b> — landmark SCOTUS case<br><br>• Nancy Cruzan: persistent vegetative state after car accident<br>• Family sought to withdraw feeding tube<br>• Missouri required 'clear and convincing evidence' of patient's wishes<br>• SCOTUS: competent persons have constitutional right to refuse life-sustaining treatment<br>• Incompetent patients: states can set evidentiary standards for surrogate decisions<br><br><i>Led to the Patient Self-Determination Act (1990) requiring hospitals to inform patients about advance directives</i>" },
  { q: "What is the <b>Patient Self-Determination Act (PSDA)</b>?", a: "Federal law (1991) requiring healthcare institutions receiving Medicare/Medicaid funding to:<br><br>1. Inform patients of their rights to make decisions about their care<br>2. Inform patients of their right to have an advance directive<br>3. Inquire and document whether patient has an advance directive<br>4. Not discriminate against patients based on advance directive status<br>5. Educate staff and community about advance directives<br><br><i>Passed in response to Cruzan decision. Applied to hospitals, nursing homes, home health agencies, hospices, and managed care organizations.</i>" },
  { q: "What is a <b>surrogate's standard</b> if patient's exact wishes are unknown?", a: "<b>Best interest standard</b> — used when substituted judgment is impossible (patient never had capacity, or wishes completely unknown)<br><br>• 'What would a reasonable person in this patient's situation want?'<br>• Considers quality of life, burdens of treatment, prognosis<br>• Surrogate must set aside their own wishes<br><br><i>Hierarchy: Substituted judgment (patient's known wishes) > best interest (reasonable person standard). Always try substituted judgment first.</i>" },
  { q: "What is the <b>Quinlan case</b> significance?", a: "<b>In re Quinlan (1976)</b> — NJ Supreme Court<br><br>• Karen Ann Quinlan: persistent vegetative state (drug/alcohol overdose)<br>• Father sought to remove ventilator<br>• NJ Supreme Court: family/guardian can authorize withdrawal of life-sustaining treatment<br><br><b>Legacy:</b><br>• Established legal right to withdraw life support<br>• Led to creation of hospital ethics committees<br>• Distinguished 'extraordinary' from 'ordinary' treatment<br><br><i>Landmark case establishing withdrawal of life support as permissible</i>" },
  { q: "What is the <b>Schiavo case</b> and its ethical significance?", a: "<b>Terri Schiavo (2005)</b>: Woman in persistent vegetative state; 15-year legal battle<br><br>• Husband (legal surrogate) sought to withdraw feeding tube per her alleged wishes<br>• Parents disagreed<br>• Congressional and presidential intervention (unusual political involvement)<br>• Courts ultimately ruled to allow withdrawal<br><br><b>Legacy:</b><br>• Highlighted importance of written advance directives<br>• Showed danger of surrogate conflict<br>• Led to increased advance directive awareness<br><br><i>Key lesson: DOCUMENT advance directives clearly and in writing</i>" },
  { q: "Can a patient <b>revoke informed consent</b> after giving it?", a: "<b>Yes</b> — a competent patient can withdraw consent at any time, even mid-procedure if possible<br><br>• Consent is not irrevocable<br>• Must stop procedure if patient withdraws consent (if clinically safe to do so)<br>• Patient must be informed that withdrawal is possible<br>• If stopping mid-procedure would cause more harm than completing it → complete and discuss after<br><br><i>Consent is an ongoing process, not a one-time event</i>" },
  { q: "What is <b>informed consent for HIV disclosure to partners</b>?", a: "Physician's duty when HIV+ patient refuses to disclose to partners:<br><br>1. Strongly encourage disclosure<br>2. May report to public health authorities (state-specific mandatory reporting)<br>3. Duty to warn partners directly: depends on state law — some require, some allow, some prohibit<br><br><b>Legal variation:</b><br>• Tarasoff-type duty may apply if specific identifiable partner at risk<br>• CDC and AMA support disclosure when non-disclosure poses serious risk<br><br><i>Document all discussions; involve ethics committee in difficult cases</i>" },
  { q: "What is the <b>'captain of the ship'</b> doctrine in surgical consent?", a: "Historical doctrine: attending surgeon bears ultimate responsibility for all actions in the operating room (including residents, nurses)<br><br>• Largely abandoned in modern law<br>• Individual providers now have independent liability<br>• Attending surgeon retains oversight responsibility<br><br><i>Relevant to informed consent: attending surgeon is ultimately responsible for ensuring valid informed consent, even if a resident obtains it. Delegation to uninformed staff is not acceptable.</i>" },
  { q: "What is <b>capacity in end-of-life decisions</b> — higher threshold?", a: "Decisions about life-sustaining treatment withdrawal carry<br><b>higher threshold</b> for demonstrating capacity (sliding scale principle)<br><br>• Must demonstrate robust understanding, appreciation, reasoning, and stable expression<br>• Psychiatry often consulted<br>• Must ensure decision is not driven by undertreated depression or delirium<br>• Document multiple capacity assessments over time<br><br><i>Key USMLE: when a patient requests withdrawal of ventilator/feeding tube, always assess capacity thoroughly and address treatable conditions (depression, pain) first</i>" },
  { q: "What is <b>surrogate consent for research</b>?", a: "When research participants lack decision-making capacity:<br><br>• LAR (Legally Authorized Representative) provides consent<br>• Research must provide direct benefit to participant OR minimal risk with benefit to group<br>• As participant gains capacity, their own consent must be obtained<br>• Participant's assent still sought<br><br><i>Additional IRB protections required when enrolling incapacitated subjects. Cannot enroll incapacitated subjects in higher-than-minimal-risk research without direct benefit.</i>" },
  { q: "What is the <b>Belmont Report</b>'s application to clinical practice?", a: "While the Belmont Report (1979) was written for research ethics, its principles apply broadly:<br><br>• <b>Respect for persons (autonomy)</b>: informed consent in clinical care<br>• <b>Beneficence</b>: acting in patient's best interest; maximizing benefit/minimizing harm<br>• <b>Justice</b>: equitable access to care; not exploiting vulnerable patients<br><br><i>Belmont principles ≈ Beauchamp & Childress 4 principles (autonomy, beneficence, non-maleficence, justice). Both frameworks are widely used in medical ethics.</i>" },
  { q: "What is the significance of <b>Schloendorff v. Society of New York Hospital (1914)</b>?", a: "Early landmark case establishing right to bodily autonomy in medicine<br><br>Judge Cardozo: '<i>Every human being of adult years and sound mind has a right to determine what shall be done with his own body; and a surgeon who performs an operation without his patient's consent commits an assault for which he is liable in damages.</i>'<br><br><i>Foundation of informed consent doctrine in US law. First major case establishing bodily autonomy as fundamental principle.</i>" },
  { q: "What are <b>exceptions to confidentiality</b> specifically for <b>adolescents</b>?", a: "Most states allow adolescent confidentiality for:<br>• STI testing/treatment<br>• Contraception<br>• Pregnancy-related care<br>• Substance abuse treatment<br>• Mental health services (varies)<br><br><b>Limits:</b><br>• Child abuse must still be reported<br>• Imminent danger to self/others → may need to notify parents<br>• Some states require parental notification for abortion<br><br><i>Goal: encourage adolescents to seek care without fear of parental disclosure. Balance adolescent confidentiality vs parental rights.</i>" },
  { q: "What is the <b>minimum necessary standard</b> under HIPAA?", a: "Healthcare providers should disclose only the <b>minimum necessary</b> PHI to accomplish the intended purpose<br><br>• When releasing records: don't share entire record if only specific info needed<br>• Workforce access: limit access to PHI based on job function<br>• Exception: treating providers — can access all necessary information for treatment (minimum necessary does not apply to treatment)<br><br><i>Reduces privacy breaches by limiting unnecessary exposure of health information</i>" },
  { q: "What is a <b>breach of confidentiality</b> vs a <b>HIPAA violation</b>?", a: "<b>Breach of confidentiality:</b> Ethical/legal violation — improper disclosure of patient health information (broader concept, common law, professional ethics)<br><br><b>HIPAA violation:</b> Specific federal statutory violation of HIPAA privacy or security rules<br><br>• A HIPAA violation is always a breach of confidentiality<br>• A breach of confidentiality may not always be a HIPAA violation (e.g., small practice not covered entity)<br><br><i>HIPAA has civil and criminal penalties. Ethical violations may result in professional sanctions.</i>" },
  { q: "What is informed consent for <b>electroconvulsive therapy (ECT)</b>?", a: "ECT requires <b>enhanced informed consent</b> due to its controversial history and risks:<br><br>• Procedure explanation (induced seizure)<br>• Risks: memory loss (anterograde/retrograde), headache, confusion, anesthesia risks<br>• Benefits for severe depression/catatonia<br>• Alternatives: medications, TMS<br>• Right to refuse and withdraw<br><br><b>Special considerations:</b><br>• If patient lacks capacity: surrogate can consent<br>• Some states require court order for ECT in incapacitated patients<br><br><i>Most states do NOT allow involuntary ECT except in extreme emergencies</i>" },
  { q: "What is the role of <b>proxy decision-making in organ transplant</b>?", a: "Competent transplant candidates consent for themselves<br><br>For incapacitated potential recipients:<br>• Surrogate can consent to organ transplantation<br>• Must apply substituted judgment or best interest standard<br>• Transplant team must ensure medical suitability<br><br>For living donors:<br>• Must be competent adults<br>• Minors and incapacitated persons generally cannot be living donors<br>• Donation must be voluntary and without undue inducement<br><br><i>Special ethics review for living donor cases — separate donor advocate required</i>" },
  { q: "What is <b>futility</b> and can it override patient/surrogate requests for treatment?", a: "<b>Medical futility</b>: Treatment that cannot achieve its physiologic goal OR offers no benefit (or is harmful) relative to goals of care<br><br>• Physicians are NOT obligated to provide clearly futile treatment<br>• <b>Quantitative futility</b>: <1% chance of success<br>• <b>Qualitative futility</b>: treatment would not achieve acceptable quality of life<br><br><i>Controversial — surrogates often demand 'everything.' Ethics committee involvement recommended. Physicians may offer treatment alternatives but cannot be forced to provide futile interventions.</i>" },
  { q: "What is 'slow code' and is it ethical?", a: "<b>Slow code</b>: Performing CPR in a perfunctory manner with no intention of achieving resuscitation (going through the motions)<br><br>• <b>UNETHICAL</b> — deceptive to family; does not honor patient dignity<br>• Violates honesty and informed consent principles<br>• If CPR is truly futile: obtain DNR order or ethics committee guidance<br>• Never appropriate as substitute for honest communication<br><br><i>The ethical alternative is an honest conversation about resuscitation goals and obtaining a DNR if appropriate</i>" },
  { q: "What is the difference between <b>withholding</b> and <b>withdrawing</b> life-sustaining treatment ethically?", a: "Ethically and legally: <b>No morally significant difference</b><br><br>• Both require patient/surrogate consent<br>• Both can be appropriate based on patient's wishes and prognosis<br>• Starting then stopping is NOT worse than never starting<br>• Emotional impact on providers may differ (harder to stop), but ethical obligations are equivalent<br><br><i>Courts (Cruzan, Quinlan) and medical ethics consistently hold withholding = withdrawal ethically. Clinicians should not be more willing to withhold than withdraw.</i>" },
  { q: "What is the <b>double effect principle</b> in ethics?", a: "An action with both a good and harmful effect may be permissible if:<br>1. The action itself is not evil<br>2. The agent intends only the good effect<br>3. The good effect doesn't flow from the bad effect<br>4. Sufficient reason exists to justify the harm<br><br><b>Medical application:</b> High-dose morphine for pain relief in dying patient may hasten death — permissible because intent is pain relief, not death<br><br><i>Distinguishes from euthanasia: intent matters. Palliative sedation is ethically permissible under this principle.</i>" },
  { q: "What is <b>palliative sedation</b> vs <b>physician-assisted suicide</b>?", a: "<b>Palliative sedation:</b> Sedatives titrated to relieve refractory suffering at end of life; may secondarily hasten death — ethical and legal<br><br><b>Physician-assisted suicide (PAS/MAID):</b> Physician prescribes lethal medication the patient self-administers — legal in some US states (OR, WA, CA, etc.)<br><br><b>Euthanasia:</b> Physician administers lethal medication — illegal in all US states<br><br><i>Key distinction: in palliative sedation, death is not the goal. In PAS, the medication directly causes death at patient's request.</i>" },
  { q: "What is <b>voluntarily stopping eating and drinking (VSED)</b>?", a: "Competent patient intentionally refuses all nutrition and hydration to hasten death<br><br>• Legal everywhere in US<br>• Ethically accepted by most professional organizations<br>• Patient must have decision-making capacity<br>• Palliative care to relieve discomfort during the process<br>• Advance directive for VSED can be made for future incapacity<br><br><i>Alternative to PAS in states where PAS is not legal. Typically takes 1-2 weeks. Hospice may support VSED patients.</i>" },
  { q: "What is the ethical issue with <b>gifts from patients</b>?", a: "<b>Gifts from patients</b>: potential conflict of interest and boundary issue<br><br>• Small, inexpensive gifts: generally acceptable<br>• Large, expensive gifts: problematic — may create sense of obligation, alter professional relationship<br>• Gifts from patients seeking prescriptions/special favors: refuse<br>• Declining a gift may be offensive; use judgment<br><br><i>Professional boundaries are essential. If uncertain, consult ethics committee or colleague.</i>" },
  { q: "What is the ethical obligation regarding <b>social media and patient privacy</b>?", a: "<b>Physicians must:</b><br>• Never post identifiable patient information without consent<br>• Never post photos/videos of patients or their conditions (even 'de-identified' if identifiable)<br>• Maintain professional boundaries with patients online<br>• Be cautious about accepting patient friend requests<br><br><i>HIPAA and professional ethics both apply online. Even de-identified cases can violate privacy if identifiable. 'What happens online, stays online.'</i>" },
  { q: "What is the role of <b>religion and spirituality</b> in informed consent?", a: "Religious/spiritual beliefs may influence patient's healthcare decisions<br><br>• Physician must respect religious-based refusals from competent adults (e.g., Jehovah's Witness blood refusal)<br>• Must ensure decision is truly the patient's own (not coerced by religious community)<br>• Physician may express concern but must ultimately respect autonomy<br>• Chaplaincy services can be helpful<br><br><i>Religion is part of patient's values — relevant to substituted judgment and advance care planning</i>" },
  { q: "What is <b>capacity for advance directive completion</b>?", a: "To complete a valid advance directive, a person must have <b>decision-making capacity</b> at the time of signing<br><br>• Written advance directives completed when patient had capacity are valid even after they lose it<br>• If patient lacks capacity when coming to hospital → existing advance directives are honored<br>• Once dementia is severe: may lack capacity to create new or modify existing ADs<br><br><i>Encourage completion of advance directives BEFORE capacity is lost. Best done during routine outpatient care.</i>" },
  { q: "What are the <b>legal requirements for an advance directive</b>?", a: "Requirements vary by state but typically include:<br><br>• Patient must be an adult (18+) and have capacity at signing<br>• Written document<br>• Dated signature<br>• Witnessed by 2 adults (typically not family members or healthcare providers)<br>• Notarization (some states)<br><br><i>Physicians should not be witnesses to advance directives of their own patients in most states. Forms available from state health departments.</i>" },
  { q: "What is a '<b>Do Not Hospitalize</b>' (DNH) order?", a: "Order used primarily in nursing home/long-term care settings indicating patient should NOT be transferred to hospital for most conditions<br><br>• Used for patients with serious illness, poor prognosis, comfort-focused goals<br>• Part of POLST/MOLST orders<br>• Emergency care and comfort care continue in facility<br>• Does not mean 'do not treat' — comfort measures continue<br><br><i>Important for seriously ill nursing home patients who prefer to die in familiar setting</i>" },
  { q: "What is the ethical framework for <b>resource allocation</b> in a pandemic (triage)?", a: "<b>Crisis standards of care</b> — ethical principles guiding allocation of scarce resources:<br><br>1. <b>Maximize lives saved</b> (utilitarian)<br>2. <b>Short-term prognosis</b> — prioritize those likely to survive<br>3. <b>Equal opportunity</b> — lottery if prognosis equal<br>4. <b>Prioritize essential workers</b> (some frameworks)<br>5. <b>First-come-first-served</b> (routine, not crisis standard)<br><br><i>Age and social utility are generally excluded from triage criteria (avoid discrimination). Triage committees vs. individual physician decisions.</i>" },
  { q: "What is the <b>Americans with Disabilities Act (ADA)</b> relevance to medical consent?", a: "ADA requires healthcare providers to provide equal access and effective communication for patients with disabilities<br><br>• Auxiliary aids: sign language interpreters, written materials in Braille, picture boards<br>• Reasonable accommodations during consent process<br>• Disability ≠ incapacity — assess capacity individually<br>• Cannot deny treatment based on disability alone<br><br><i>The consent process must be accessible. A deaf patient has the right to a sign language interpreter for informed consent discussions.</i>" },
  { q: "What is <b>medical futility</b> vs <b>physician discomfort</b>?", a: "<b>Medical futility:</b> Objective determination that treatment cannot achieve physiologic goal<br><br><b>Physician discomfort:</b> Subjective feeling that a patient's treatment choice is unwise or burdensome to provide<br><br>• Physician discomfort is NOT futility<br>• Cannot withhold beneficial treatment due to physician's value judgment<br>• Can express disagreement and offer alternatives<br>• Can seek ethics committee guidance<br><br><i>Physicians have limited leeway to impose their values. True futility is a narrow concept.</i>" },
  { q: "What is the <b>four-box method</b> of clinical ethics consultation?", a: "Structured approach to clinical ethics analysis (Jonsen, Siegler, Winslade):<br><br>1. <b>Medical indications</b>: diagnosis, prognosis, goals of treatment, benefits/burdens<br>2. <b>Patient preferences</b>: values, informed decisions, advance directives, capacity<br>3. <b>Quality of life</b>: patient's perspective on acceptable quality, biases of caregivers<br>4. <b>Contextual features</b>: family, culture, religion, finances, law, resource allocation<br><br><i>Systematically ensures all ethical dimensions are considered in complex cases</i>" },
];
